// SPDX-License-Identifier: MIT
pragma solidity 0.8.34;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IStandardBridge} from "./interfaces/IStandardBridge.sol";
import {IAllowanceModule} from "./interfaces/IAllowanceModule.sol";

/// @notice WARNING: Unaudited demo contract. Not ready for production use.
/// Bounded Ethereum spending delegate controlled by one rollup policy.
/// @dev The Safe binds its policy alias once and grants the official module's
/// allowance separately. Transfer, approval and bridging share one L1 call so
/// execution does not depend on several mutable L1 callback snapshots. No module
/// authority, owner keys or arbitrary external calls are granted to this delegate.
contract StandardBridgeDelegate {
    using SafeERC20 for IERC20;
    address public immutable safe;
    IAllowanceModule public immutable allowance;
    IERC20 public immutable token;
    IStandardBridge public immutable bridge;
    uint64 public immutable rollupId;
    address public policyAlias;
    bool private entered;

    error OnlySafe();
    error OnlyPolicy();
    error InvalidConfiguration();
    error ResidualFunds();
    error Reentered();
    event PolicyBound(address indexed policyAlias);

    constructor(address safe_, IAllowanceModule allowance_, IERC20 token_, IStandardBridge bridge_, uint64 rollup) {
        if (
            safe_.code.length == 0 || address(allowance_).code.length == 0 || address(token_).code.length == 0
                || bridge_.rollupId() != 0 || rollup == 0
        ) revert InvalidConfiguration();
        safe = safe_;
        allowance = allowance_;
        token = token_;
        bridge = bridge_;
        rollupId = rollup;
    }

    function bindPolicy(address alias_) external {
        if (msg.sender != safe) revert OnlySafe();
        if (policyAlias != address(0) || alias_.code.length == 0) revert InvalidConfiguration();
        policyAlias = alias_;
        emit PolicyBound(alias_);
    }

    function pay(address recipient, uint256 amount, bool onL1) external {
        if (msg.sender != policyAlias) revert OnlyPolicy();
        if (entered) revert Reentered();
        if (amount == 0 || amount > type(uint96).max || recipient == address(0) || recipient == address(this)) {
            revert InvalidConfiguration();
        }
        entered = true;
        uint256 beforeBalance = token.balanceOf(address(this));
        allowance.executeAllowanceTransfer(
            safe,
            address(token),
            payable(onL1 ? recipient : address(this)),
            uint96(amount),
            address(0),
            0,
            address(this),
            ""
        );
        if (!onL1) {
            if (token.balanceOf(address(this)) != beforeBalance + amount) revert ResidualFunds();
            token.forceApprove(address(bridge), amount);
            bridge.bridgeTokens(address(token), amount, rollupId, recipient);
            if (token.allowance(address(this), address(bridge)) != 0) revert ResidualFunds();
        }
        if (token.balanceOf(address(this)) != beforeBalance) revert ResidualFunds();
        entered = false;
    }
}

src/StandardBridgeTreasuryPolicy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.34;

import {TreasuryPolicyBase} from "./TreasuryPolicyBase.sol";
import {IEEZProxyRegistry} from "./interfaces/IEEZProxyRegistry.sol";
import {IAllowanceModule} from "./interfaces/IAllowanceModule.sol";
import {IStandardBridge} from "./interfaces/IStandardBridge.sol";
import {StandardBridgeDelegate} from "./StandardBridgeDelegate.sol";

/// @notice A single canonical USDC budget over two Safe allowance delegates.
/// @dev Submit either Safe through its L1 entry point so standard bridge callbacks
///      remain within the pinned signer profile. Accounting is inherited unchanged.
contract StandardBridgeTreasuryPolicy is TreasuryPolicyBase {
    IStandardBridge public immutable bridgeL1Proxy;
    address public immutable bridgeExecutorL1;
    StandardBridgeDelegate public immutable bridgeExecutorL1Proxy;

    constructor(
        address safeL1_,
        address safeL2_,
        IEEZProxyRegistry manager,
        address moduleL1,
        IAllowanceModule moduleL2,
        address token,
        IStandardBridge bridge_,
        address executor
    )
        TreasuryPolicyBase(safeL1_, safeL2_, manager, moduleL1, moduleL2, token, bridge_)
    {
        if (executor == address(0)) revert InvalidConfiguration();
        bridgeL1Proxy = IStandardBridge(manager.getOrCreateCrossChainProxy(bridgeL1, 0));
        bridgeExecutorL1 = executor;
        bridgeExecutorL1Proxy = StandardBridgeDelegate(manager.getOrCreateCrossChainProxy(executor, 0));
    }

    function _paymentContext() internal view override returns (address alias_, address delegate) {
        if (bridgeL1Proxy.canonicalBridgeAddress() != address(bridge) || bridgeL1Proxy.rollupId() != 0) {
            revert InvalidConfiguration();
        }
        // The Safe binds its delegate once. The client also validates that binding
        // against the registry before accepting the selected treasury.
        alias_ = bridgeExecutorL1Proxy.policyAlias();
        if (alias_ == address(0)) revert InvalidConfiguration();
        delegate = bridgeExecutorL1;
    }

    function _payL1(address, address recipient, uint256 amount, bool onL1) internal override {
        bridgeExecutorL1Proxy.pay(recipient, amount, onL1);
    }
}

src/TreasuryPolicyBase.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.34;

import {IEEZProxyRegistry} from "./interfaces/IEEZProxyRegistry.sol";
import {IAllowanceModule} from "./interfaces/IAllowanceModule.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IStandardBridge} from "./interfaces/IStandardBridge.sol";
import {ISafe} from "./interfaces/ISafe.sol";

/// @notice WARNING: Unaudited demo contract. Not ready for production use.
/// Shared authorization, accounting and payments for the two treasury bridge paths.
/// @dev Bridge adapters authenticate their remote spending delegate and execute
///      the L1 contribution. They inherit this code without another deployment.
///      Only official allowance modules have Safe module power. Remote view calls
///      require EEZ execution tables; owner administration remains unrestricted.
abstract contract TreasuryPolicyBase {
    address public immutable safeL1Proxy;
    event L1PaymentAuthorized(uint256 indexed safeNonce, bytes32 indexed callHash);
    uint256 public constant SPLIT_VERSION = 1;
    uint256 public constant PERIOD = 600;
    uint256 public constant BPS_DENOMINATOR = 10_000;
    uint256 public constant GLOBAL_LIMIT = 150_000_000;
    uint256 public constant PER_PAYMENT = 150_000_000;
    address public immutable safeL1;
    address public immutable safeL2;
    address public immutable canonicalToken;
    address public immutable wrappedToken;
    IAllowanceModule public immutable allowanceL2;
    IAllowanceModule public immutable allowanceL1Proxy;
    IERC20 public immutable tokenL1Proxy;
    uint64 public immutable rollupId;
    IStandardBridge public immutable bridge;
    address public immutable bridgeL1;
    mapping(uint256 epoch => uint256 amount) public spent;
    bool private entered;

    error OnlySafe();
    error InvalidConfiguration();
    error InvalidAsset();
    error InvalidRecipient();
    error InvalidAmount();
    error InvalidFraction();
    error StaleEpoch();
    error GlobalLimit();
    error Capacity();
    error UnalignedAllowance();
    error ApprovalFailed();
    error Reentered();
    error ResidualBalance();
    event Paid(
        address indexed token,
        address indexed recipient,
        bool onL1,
        uint256 amount,
        uint256 fromL1,
        uint256 fromL2,
        uint256 epoch
    );

    event RulePaid(
        address indexed token,
        address indexed recipient,
        bool onL1,
        uint16 bps,
        uint256 balanceL1,
        uint256 balanceL2,
        uint256 amount,
        uint256 epoch
    );

    // Hold the same authorization/reentrancy boundary across rule reads and all
    // payment legs. Each public entry point shares it; no self-call is needed.
    modifier paymentExecution() {
        _authorizePayment();
        if (entered) revert Reentered();
        entered = true;
        _;
        entered = false;
    }

    function _authorizePayment() private {
        if (msg.sender == safeL2) return;
        if (msg.sender != safeL1Proxy) revert OnlySafe();
        emit L1PaymentAuthorized(ISafe(safeL1Proxy).nonce(), keccak256(msg.data));
    }

    constructor(
        address safeL1_,
        address safeL2_,
        IEEZProxyRegistry manager,
        address moduleL1,
        IAllowanceModule moduleL2,
        address token,
        IStandardBridge bridge_
    ) {
        if (
            safeL1_ == address(0) || safeL2_.code.length == 0 || address(moduleL2).code.length == 0
                || moduleL1 == address(0) || token == address(0) || manager.ROLLUP_ID() == 0
                || address(bridge_.manager()) != address(manager) || bridge_.rollupId() != manager.ROLLUP_ID()
                || bridge_.canonicalBridgeAddress() == address(0)
        ) revert InvalidConfiguration();
        address wrapped = bridge_.getWrappedToken(token, 0);
        (address original, uint64 origin) = bridge_.wrappedTokenInfo(wrapped);
        if (wrapped.code.length == 0 || original != token || origin != 0) revert InvalidConfiguration();
        address proxy = manager.getOrCreateCrossChainProxy(safeL1_, 0);
        (bool registered, address owner, uint64 chain) = manager.authorizedProxies(proxy);
        if (!registered || owner != safeL1_ || chain != 0 || proxy.code.length == 0) revert InvalidConfiguration();
        safeL1Proxy = proxy;
        safeL1 = safeL1_;
        safeL2 = safeL2_;
        canonicalToken = token;
        wrappedToken = wrapped;
        allowanceL2 = moduleL2;
        bridge = bridge_;
        bridgeL1 = bridge_.canonicalBridgeAddress();
        rollupId = manager.ROLLUP_ID();
        // Provision local proxies outside STATICCALL. The deployment must also
        // provision this policy's L1 alias before its first remote read.
        allowanceL1Proxy = IAllowanceModule(manager.getOrCreateCrossChainProxy(moduleL1, 0));
        tokenL1Proxy = IERC20(manager.getOrCreateCrossChainProxy(token, 0));
    }

    /// @notice Pay exactly the contributions approved by the owners, on either chain.
    /// @dev The remainder comes from SafeL2. Never rebalance a signed allocation
    ///      when capacity changes; fail before either transfer instead.
    function paySplit(
        address token,
        address recipient,
        uint256 amount,
        bool onL1,
        uint256 expectedEpoch,
        uint256 fromL1
    )
        external
        paymentExecution
    {
        if (fromL1 > amount) revert InvalidAmount();
        _pay(token, recipient, amount, onL1, expectedEpoch, fromL1);
    }

    /// @notice Pay a fraction of both Safe holdings using destination-first routing.
    /// @dev Owners authorize the fraction, not a fixed preview amount. Both balances
    ///      are read before transfers; escrow and temporary policy custody are not
    ///      holdings. Rounds down to token base units. Zero or over-limit results,
    ///      an invalid fraction/epoch and insufficient capacity revert the payment.
    function payRule(
        address token,
        address recipient,
        uint16 bps,
        bool onL1,
        uint256 expectedEpoch
    )
        external
        paymentExecution
    {
        if (token != canonicalToken) revert InvalidAsset();
        if (expectedEpoch != block.timestamp / PERIOD) revert StaleEpoch();
        if (bps == 0 || bps > BPS_DENOMINATOR) revert InvalidFraction();
        uint256 balanceL1 = tokenL1Proxy.balanceOf(safeL1);
        uint256 balanceL2 = IERC20(wrappedToken).balanceOf(safeL2);
        uint256 amount = Math.mulDiv(balanceL1 + balanceL2, bps, BPS_DENOMINATOR);
        _pay(token, recipient, amount, onL1, expectedEpoch, type(uint256).max);
        emit RulePaid(canonicalToken, recipient, onL1, bps, balanceL1, balanceL2, amount, expectedEpoch);
    }

    function _pay(
        address token,
        address recipient,
        uint256 amount,
        bool onL1,
        uint256 expectedEpoch,
        uint256 requestedL1
    )
        internal
    {
        if (token != canonicalToken) revert InvalidAsset();
        if (amount == 0 || amount > PER_PAYMENT || amount > type(uint96).max) revert InvalidAmount();
        uint256 epoch = block.timestamp / PERIOD;
        if (expectedEpoch != epoch) revert StaleEpoch();
        if (spent[epoch] + amount > GLOBAL_LIMIT) revert GlobalLimit();
        if (bridge.canonicalBridgeAddress() != bridgeL1) revert InvalidConfiguration();
        (address alias_, address delegate) = _paymentContext();
        if (
            recipient == address(0) || recipient == address(this) || recipient == alias_ || recipient == safeL1
                || recipient == safeL2 || recipient == address(bridge) || recipient == bridgeL1 || recipient == delegate
        ) revert InvalidRecipient();
        uint256 fromL1;
        uint256 fromL2;
        if (requestedL1 != type(uint256).max) {
            fromL1 = requestedL1;
            fromL2 = amount - fromL1;
            if (fromL1 > _capacity(true, delegate, epoch) || fromL2 > _capacity(false, delegate, epoch)) {
                revert Capacity();
            }
        } else if (onL1) {
            uint256 cap = _capacity(true, delegate, epoch);
            fromL1 = amount < cap ? amount : cap;
            fromL2 = amount - fromL1;
            if (fromL2 > 0 && fromL2 > _capacity(false, delegate, epoch)) revert Capacity();
        } else {
            uint256 cap = _capacity(false, delegate, epoch);
            fromL2 = amount < cap ? amount : cap;
            fromL1 = amount - fromL2;
            if (fromL1 > 0 && fromL1 > _capacity(true, delegate, epoch)) revert Capacity();
        }
        spent[epoch] += amount;
        // Execute the L2 contribution first. Required failures propagate through
        // the Safe's zero-refund execution, including a later L1 lock failure.
        if (fromL2 > 0) {
            uint256 beforeBalance = IERC20(wrappedToken).balanceOf(address(this));
            allowanceL2.executeAllowanceTransfer(
                safeL2,
                wrappedToken,
                payable(onL1 ? address(this) : recipient),
                uint96(fromL2),
                address(0),
                0,
                address(this),
                ""
            );
            if (onL1) bridge.bridgeTokens(wrappedToken, fromL2, 0, recipient);
            if (IERC20(wrappedToken).balanceOf(address(this)) != beforeBalance) revert ResidualBalance();
        }
        if (fromL1 > 0) _payL1(alias_, recipient, fromL1, onL1);
        emit Paid(canonicalToken, recipient, onL1, amount, fromL1, fromL2, epoch);
    }

    function _capacity(bool onL1, address delegate, uint256 epoch) private view returns (uint256) {
        uint256 remaining = _remaining(
            onL1 ? allowanceL1Proxy : allowanceL2,
            onL1 ? safeL1 : safeL2,
            onL1 ? delegate : address(this),
            onL1 ? canonicalToken : wrappedToken,
            epoch
        );
        uint256 balance = onL1 ? tokenL1Proxy.balanceOf(safeL1) : IERC20(wrappedToken).balanceOf(safeL2);
        return balance < remaining ? balance : remaining;
    }

    function _remaining(
        IAllowanceModule module,
        address safe,
        address delegate,
        address token,
        uint256 epoch
    )
        internal
        view
        returns (uint256)
    {
        uint256[5] memory a = module.getTokenAllowance(safe, delegate, token);
        // Refuse mismatched periods or L1/L2 timestamp epochs instead of combining
        // different windows. The owners sign expectedEpoch, so delayed approval
        // cannot silently spend against a later period's budget.
        if (a[2] != PERIOD / 60 || a[3] != epoch * (PERIOD / 60)) revert UnalignedAllowance();
        return a[1] < a[0] ? a[0] - a[1] : 0;
    }
    /// @dev Return this policy's authenticated alias and L1 allowance beneficiary.
    ///      Adapters must reject unbound delegates or a changed bridge peer.
    function _paymentContext() internal view virtual returns (address alias_, address delegate);

    /// @dev Execute the complete L1 contribution, including bridging when needed.
    ///      Any failed transfer, residual custody or approval must revert.
    function _payL1(address alias_, address recipient, uint256 amount, bool onL1) internal virtual;
}

