    function getTokenAllowance(
        address safe,
        address delegate,
        address token
    )
        external
        view
        returns (uint256[5] memory allowance);
    function executeAllowanceTransfer(
        address safe,
        address token,
        address payable to,
        uint96 amount,
        address paymentToken,
        uint96 payment,
        address delegate,
        bytes calldata signature
    )
        external;
}

